mapper.insert:
/* 외부 API 호출 로그 추가 */
INSERT INTO EXTL_API_CALL_LOG (EXTL_API_SE_CD
                             , CALL_RSLT_CD
                             , MBR_SN
                             , CALL_DT
                             , RSPNS_MS
                             , HTTP_STTS_VL
                             , INPT_TKN_CNT
                             , OTPT_TKN_CNT
                             , FAIL_RSN)
VALUES (#{extlApiSeCd}
      , #{callRsltCd}
      , #{mbrSn}
      , COALESCE(#{callDt}, NOW())
      , #{rspnsMs}
      , #{httpSttsVl}
      , #{inptTknCnt}
      , #{otptTknCnt}
      , #{failRsn})

mapper.sql:
AND CALL_DT >= #{cond.bgngYmd}
AND CALL_DT < DATE_ADD(#{cond.endYmd}, INTERVAL 1 DAY)

AND EXTL_API_SE_CD = #{cond.extlApiSeCd}

mapper.select:
/* AI 일별 토큰 조회 */ SELECT DATE(CALL_DT) AS CALL_YMD , COALESCE(SUM(INPT_TKN_CNT), 0) AS INPT_TKN_CNT , COALESCE(SUM(OTPT_TKN_CNT), 0) AS OTPT_TKN_CNT FROM EXTL_API_CALL_LOG WHERE EXTL_API_SE_CD IN
#{aiCode}
GROUP BY DATE(CALL_DT) ORDER BY CALL_YMD DESC
